style.css:
@-moz-document domain("instagram.com") {
/* Fondo general */
  body, header, main, section {
    background-color: #f5c1cf !important; /* rosa nude fuerte */
  }

  /* NOTAS (la burbujita arriba) */
  div[role="dialog"],
  div[style*="note"] {
    background-color: #e8a9b8 !important; /* nude rosado más intenso */
    border-radius: 14px !important;
  }

  /* Texto dentro de notas */
  div[role="dialog"] span {
    color: #4a2a32 !important; /* texto oscuro elegante */
  }

  /* CÍRCULOS DE DESTACADAS (bordes blancos) */
  canvas,
  svg circle {
    stroke: #e3a1b2 !important; /* nude rosado fuerte */
  }

  /* Borde externo de destacadas */
  img[alt*="profile picture"] {
    outline: 4px solid #e3a1b2 !important;
    border-radius: 50% !important;
  }

  /* Quitar blancos feos */
  article, div {
    background-color: transparent !important;
  }
}
